const moveFile = async (siteUrl, sourceFileId, destinationFolderPath, newFileName, oOptions = {}) => _dbgWrap("moveFile", [siteUrl, sourceFileId, destinationFolderPath, newFileName, oOptions], async function() {
  if (typeof newFileName === "object" && newFileName !== null && !Array.isArray(newFileName)) {
    oOptions = newFileName;
    newFileName = pickSharePointValue(oOptions.newFileName, oOptions.name);
  }

  const sDataset = normalizeSharePointDataset(siteUrl);
  const oResult = await executeConnectorOperation("MoveFileAsync", {
    dataset: sDataset,
    parameters: {
      sourceFileId: requireNonEmptyString(String(sourceFileId || ""), "source file ID"),
      destinationDataset: pickSharePointValue(oOptions.destinationSiteUrl, oOptions.destinationDataset, sDataset),
      destinationFolderPath: requireNonEmptyString(destinationFolderPath, "destination folder path"),
      nameConflictBehavior: pickSharePointValue(oOptions.nameConflictBehavior, 1)
    }
  });

  if (newFileName) {
    const sMovedFileId = pickSharePointValue(oResult && oResult.Id, oResult && oResult.id, oResult && oResult.ItemId, oResult && oResult.itemId);
    if (sMovedFileId) {
      return renameFile(sDataset, sMovedFileId, newFileName);
    }
  }

  return oResult;
});

